window.CARDS=window.CARDS||{};CARDS["people-nanase-tsubasa"]=[{"i":"sc-nanase-tsubasa-y2v1-p7-1","v":"y2v1","y":2,"o":16,"k":"","w":"tsukishiro ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa prologue  briefed by tsukishiro in a tokyo facility  nanase  unnamed  listens as tsukishiro briefs her on ayanokoji kiyotaka  shows signs of dissatisfaction that ayanokoji is praised as the white room s masterpiece  leaves the room calmly after being asked whether she is hiding something  is briefed and sent to the school  is ordered to help expel him","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p7-1\"><h3><span class=\"ttl\">Prologue: Briefed by Tsukishiro<\/span><span class=\"meta\">Y2V1 · p.7–11<\/span><\/h3><p class=\"setup\">In a Tokyo facility, Nanase (unnamed) listens as Tsukishiro briefs her on Ayanokōji Kiyotaka. Shows signs of dissatisfaction that Ayanokōji is praised as the White Room’s masterpiece. Leaves the room calmly after being asked whether she is hiding something.<\/p><p class=\"with\">with <a href=\"tsukishiro.html\">Tsukishiro<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Is briefed and sent to the school.<span class=\"pg\">p.7–11<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is ordered to help expel him.<span class=\"pg\">p.7–11<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p7-2\">→ After: Prologue: Briefed by Tsukishiro<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p7-2","v":"y2v1","y":2,"o":16,"k":"","w":"tsukishiro ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa prologue  briefed by tsukishiro in a tokyo facility  nanase  unnamed  listens as tsukishiro briefs her on ayanokoji kiyotaka  shows signs of dissatisfaction that ayanokoji is praised as the white room s masterpiece  leaves the room calmly after being asked whether she is hiding something  is briefed and sent to the school  is ordered to help expel him","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p7-2\"><h3><span class=\"ttl\">Prologue: Briefed by Tsukishiro<\/span><span class=\"meta\">Y2V1 · p.7–11<\/span><\/h3><p class=\"setup\">In a Tokyo facility, Nanase (unnamed) listens as Tsukishiro briefs her on Ayanokōji Kiyotaka. Shows signs of dissatisfaction that Ayanokōji is praised as the White Room’s masterpiece. Leaves the room calmly after being asked whether she is hiding something.<\/p><p class=\"with\">with <a href=\"tsukishiro.html\">Tsukishiro<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Is briefed and sent to the school.<span class=\"pg\">p.7–11<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is ordered to help expel him.<span class=\"pg\">p.7–11<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p7-1\">← Before: Prologue: Briefed by Tsukishiro<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p79-1\">→ After: Ch.3: Class 1-D hallway<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p79-1","v":"y2v1","y":2,"o":16,"k":"","w":"housen-kazuomi ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa ch 3  class 1 d hallway accompanies hosen to class 2 d  stops hosen by referencing  that  apologizes to the second years and bows  looks at ayanokoji before leaving  accompanies and restrains him  looks at him","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p79-1\"><h3><span class=\"ttl\">Ch.3: Class 1-D hallway<\/span><span class=\"meta\">Y2V1 · p.79–95<\/span><\/h3><p class=\"setup\">Accompanies Hōsen to Class 2-D. Stops Hōsen by referencing “that”. Apologizes to the second-years and bows. Looks at Ayanokōji before leaving.<\/p><p class=\"with\">with <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Accompanies and restrains him.<span class=\"pg\">p.79–95<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Looks at him.<span class=\"pg\">p.95<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p7-2\">← Before: Prologue: Briefed by Tsukishiro<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p100-1\">→ After: Nanase with Hōsen; a probing look at Ayanokōji<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p100-1","v":"y2v1","y":2,"o":16,"k":"spoken","w":"ayanokouji-kiyotaka housen-kazuomi nanase-tsubasa","q":"nanase tsubasa nanase with hosen  a probing look at ayanokoji accompanies hosen during his confrontation with ryuen  and obeys his order to withdraw   yes  that s a wise choice   i m sorry for the disturbance  calm and composed beside the volatile hosen   bows a polite final apology on behalf of class 1 d  when she raises her head she fixes ayanokoji with the same inquisitive  probing look as when she first arrived  then quickly looks away and runs after hosen  gives him a knowing  probing look   the white room agent silently assessing her target  obeys his withdrawal order  seen as his second in command in class 1 d","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p100-1\"><h3><span class=\"ttl\">Nanase with Hōsen; a probing look at Ayanokōji<\/span><span class=\"meta\">Y2V1 · p.100–101<\/span><\/h3><p class=\"setup\">Accompanies Hōsen during his confrontation with Ryūen, and obeys his order to withdraw.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Yes. That&#x27;s a wise choice.&quot;<span class=\"pg\">p.100<\/span><\/li><li class=\"q spoken\">&quot;I&#x27;m sorry for the disturbance.&quot;<span class=\"pg\">p.101<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Calm and composed beside the volatile Hōsen — bows a polite final apology on behalf of Class 1-D; when she raises her head she fixes Ayanokōji with the same inquisitive, probing look as when she first arrived, then quickly looks away and runs after Hōsen.<span class=\"pg\">p.100–101<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Gives him a knowing, probing look — the White Room agent silently assessing her target.<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Obeys his withdrawal order; seen as his second-in-command in Class 1-D.<span class=\"pg\">p.100–101<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p79-1\">← Before: Ch.3: Class 1-D hallway<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p142-1\">→ After: Ch.4: Approaching Ayanokōji<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p142-1","v":"y2v1","y":2,"o":16,"k":"","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa ch 4  approaching ayanokoji greets ayanokoji on the way to school  apologizes for hosen s rudeness  discusses cooperation between class 1 d and 2 d  says she will never yield to violence  agrees to set something up for him  approaches and proposes cooperation","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p142-1\"><h3><span class=\"ttl\">Ch.4: Approaching Ayanokōji<\/span><span class=\"meta\">Y2V1 · p.142–155<\/span><\/h3><p class=\"setup\">Greets Ayanokōji on the way to school. Apologizes for Hōsen’s rudeness. Discusses cooperation between Class 1-D and 2-D. Says she will never yield to violence. Agrees to set something up for him.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Approaches and proposes cooperation.<span class=\"pg\">p.148–155<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p100-1\">← Before: Nanase with Hōsen; a probing look at Ayanokōji<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p204-1\">→ After: Ch.5: Library meeting and strategy<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p204-1","v":"y2v1","y":2,"o":16,"k":"","w":"horikita-suzune ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa ch 5  library meeting and strategy meets horikita and ayanokoji in the library  reveals class 1 d s situation and proposes becoming leader  explains hosen s individualist policy  proposes secret negotiations to horikita  tests ayanokoji s character  explains class 1 d started with 800 class points  negotiates with her  discusses cooperation with him","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p204-1\"><h3><span class=\"ttl\">Ch.5: Library meeting and strategy<\/span><span class=\"meta\">Y2V1 · p.204–242<\/span><\/h3><p class=\"setup\">Meets Horikita and Ayanokōji in the library. Reveals Class 1-D’s situation and proposes becoming leader. Explains Hōsen’s individualist policy. Proposes secret negotiations to Horikita. Tests Ayanokōji’s character. Explains Class 1-D started with 800 class points.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Negotiates with her.<span class=\"pg\">p.204–233<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Discusses cooperation with him.<span class=\"pg\">p.204–242<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p142-1\">← Before: Ch.4: Approaching Ayanokōji<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p205-1\">→ After: Nanase negotiates on behalf of Class 1-D<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p205-1","v":"y2v1","y":2,"o":16,"k":"spoken","w":"horikita-suzune housen-kazuomi ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa nanase negotiates on behalf of class 1 d arrives alone at the library for the discussion with horikita and ayanokoji  fumbles her self introduction  starting with the masculine  boku  a detail the translation flags   i  no  that s not right  i am known as nanase tsubasa  i haven t done anything worthy of your thanks   many students have already begun taking action in accordance with hosen kun s orders   i m immensely sorry  but i m afraid i can t provide you with any specifics   an act of betrayal   our doors are always open to you  as long as you present us with at least a fixed number of private points  we ll accept the partnership without the slightest bit of hesitation   what really gets to me is the thought that this individualistic mindset might never go away  preventing us from being able to unite as a class in the future   yes    when asked if she fears hosen  at this point  i believe that approximately fifteen students would find it difficult to search for a partner on their own   hosen kun would never allow us to help you out for free  especially not now   hosen kun has not received any compensation from our classmates  upright  fearless and loyal   refuses to leak hosen s strategy  calling it betrayal  admits she fears him yet opposes his individualism for the class s future  and reveals he takes no profit  she negotiates single handedly to save the weak  negotiates the 15 pair equal cooperation proposal with her  confirms he controls class 1 d via orders  with no personal compensation  she opposes his individualist policy  treats him with respect  fixes her  same look  on him   the hidden white room agent quietly assessing her target","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p205-1\"><h3><span class=\"ttl\">Nanase negotiates on behalf of Class 1-D<\/span><span class=\"meta\">Y2V1 · p.205–214<\/span><\/h3><p class=\"setup\">Arrives alone at the library for the discussion with Horikita and Ayanokōji; fumbles her self-introduction (starting with the masculine &quot;Boku,&quot; a detail the translation flags).<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;I─ No, that&#x27;s not right… I am known as Nanase Tsubasa. I haven&#x27;t done anything worthy of your thanks.&quot;<span class=\"pg\">p.208<\/span><\/li><li class=\"q spoken\">&quot;Many students have already begun taking action in accordance with Hōsen-kun&#x27;s orders.&quot;<span class=\"pg\">p.209<\/span><\/li><li class=\"q spoken\">&quot;I&#x27;m immensely sorry, but I&#x27;m afraid I can&#x27;t provide you with any specifics.&quot;<span class=\"pg\">p.209<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;an act of betrayal.&quot;<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;our doors are always open to you. As long as you present us with at least a fixed number of private points, we&#x27;ll accept the partnership without the slightest bit of hesitation.&quot;<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;What really gets to me is the thought that this individualistic mindset might never go away, preventing us from being able to unite as a class in the future.&quot;<span class=\"pg\">p.211<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Yes.&quot; — when asked if she fears Hōsen<span class=\"pg\">p.211<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;At this point, I believe that approximately fifteen students would find it difficult to search for a partner on their own.&quot;<span class=\"pg\">p.212<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Hōsen-kun would never allow us to help you out for free. Especially not now.&quot;<span class=\"pg\">p.213<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Hōsen-kun has not received any compensation from our classmates.&quot;<span class=\"pg\">p.214<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Upright, fearless and loyal — refuses to leak Hōsen&#x27;s strategy (calling it betrayal), admits she fears him yet opposes his individualism for the class&#x27;s future, and reveals he takes no profit; she negotiates single-handedly to save the weak.<span class=\"pg\">p.208–214<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Negotiates the 15-pair equal-cooperation proposal with her.<span class=\"pg\">p.208–214<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Confirms he controls Class 1-D via orders, with no personal compensation; she opposes his individualist policy.<span class=\"pg\">p.209–214<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Treats him with respect; fixes her &quot;same look&quot; on him — the hidden White Room agent quietly assessing her target.<span class=\"pg\">p.208–214<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p204-1\">← Before: Ch.5: Library meeting and strategy<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p290-1\">→ After: Ch.6: Mediating and revealing<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p290-1","v":"y2v1","y":2,"o":16,"k":"","w":"housen-kazuomi horikita-suzune ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa ch 6  mediating and revealing mediates between horikita and hosen  tries to stop hosen from leaving  explains nagumo s tolerance of fighting  proposes mutual trust  warns horikita about hosen s true nature  blocks hosen from stabbing ayanokoji  explains the 20 million point bounty and hosen s plan  reveals her true feelings toward ayanokoji  mediates for him  negotiates with her  explains to him","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p290-1\"><h3><span class=\"ttl\">Ch.6: Mediating and revealing<\/span><span class=\"meta\">Y2V1 · p.290–335<\/span><\/h3><p class=\"setup\">Mediates between Horikita and Hōsen. Tries to stop Hōsen from leaving. Explains Nagumo’s tolerance of fighting. Proposes mutual trust. Warns Horikita about Hōsen’s true nature. Blocks Hōsen from stabbing Ayanokōji. Explains the 20-million-point bounty and Hōsen’s plan. Reveals her true feelings toward Ayanokōji.<\/p><p class=\"with\">with <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Mediates for him.<span class=\"pg\">p.290–331<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Negotiates with her.<span class=\"pg\">p.290–333<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Explains to him.<span class=\"pg\">p.333–335<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p205-1\">← Before: Nanase negotiates on behalf of Class 1-D<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p326-1\">→ After: Nanase stops Hōsen; reveals the 20-million bounty and her hatred<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p326-1","v":"y2v1","y":2,"o":16,"k":"spoken","w":"housen-kazuomi horikita-suzune ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa nanase stops hosen  reveals the 20 million bounty and her hatred steps between hosen and ayanokoji as he advances with the knife  spreading her arms to block him   please don t go any further  i can t approve of your methods after all  i can t   i made the decision to lend you my strength until the very end  telling myself that it was for the good of the class   horikita senpai  working together with hosen kun has been impossible from the very beginning   that was just a ploy to get things to progress to this point   no  nothing of the sort  horikita senpai  i truly did want to join hands with you and establish a supporting relationship between our two classes   we were told that the student who manages to expel ayanokoji kiyotaka of class 2 d will receive a bulk sum of 20 million private points  that s the special exam that was given to us   for the sake of my class  of class 1 d  i chose to cooperate with hosen kun knowing full well just how awful his methods truly were   because  if the 20 million point bounty were to fall into the hands of another class  it would bring about serious ramifications for us moving forward   i  simply didn t believe a person like you would be suitable for this school  ayanokoji senpai  breaks with hosen to stop the knife  reveals the negotiation was a ploy from the start and the 20 million point bounty  and explains she cooperated to keep the bounty from another class   then reveals an unexplained personal hatred  using the masculine katakana  boku  in her final line  deliberately linking herself to ayanokoji  per the translation notes  physically stops him  declares she was wrong to accept his methods  and is brushed aside  reveals the plot and bounty to her and ayanokoji  urges them to beware other first year classes  directs open hatred at him   the white room agent s true motive remains hidden  she stays behind to explain  then leaves","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p326-1\"><h3><span class=\"ttl\">Nanase stops Hōsen; reveals the 20-million bounty and her hatred<\/span><span class=\"meta\">Y2V1 · p.326–341<\/span><\/h3><p class=\"setup\">Steps between Hōsen and Ayanokōji as he advances with the knife, spreading her arms to block him.<\/p><p class=\"with\">with <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Please don&#x27;t go any further! I can&#x27;t approve of your methods after all… I can&#x27;t!&quot;<span class=\"pg\">p.326<\/span><\/li><li class=\"q spoken\">&quot;I made the decision to lend you my strength until the very end, telling myself that it was for the good of the class.&quot;<span class=\"pg\">p.328<\/span><\/li><li class=\"q spoken\">&quot;Horikita-senpai, working together with Hōsen-kun has been impossible from the very beginning.&quot;<span class=\"pg\">p.328<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;That was just a ploy to get things to progress to this point.&quot;<span class=\"pg\">p.328<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;No, nothing of the sort, Horikita-senpai. I truly did want to join hands with you and establish a supporting relationship between our two classes.&quot;<span class=\"pg\">p.340<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;We were told that the student who manages to expel Ayanokōji Kiyotaka of Class 2-D will receive a bulk sum of 20 million private points. That&#x27;s the special exam that was given to us.&quot;<span class=\"pg\">p.340<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;For the sake of my class, of Class 1-D, I chose to cooperate with Hōsen-kun knowing full well just how awful his methods truly were.&quot;<span class=\"pg\">p.341<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Because, if the 20 million point bounty were to fall into the hands of another class, it would bring about serious ramifications for us moving forward.&quot;<span class=\"pg\">p.341<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I*… simply didn&#x27;t believe a person like you would be suitable for this school, Ayanokōji-senpai.&quot;<span class=\"pg\">p.341<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Breaks with Hōsen to stop the knife, reveals the negotiation was a ploy from the start and the 20-million-point bounty, and explains she cooperated to keep the bounty from another class — then reveals an unexplained personal hatred, using the masculine katakana &quot;boku&quot; in her final line (deliberately linking herself to Ayanokōji, per the translation notes).<span class=\"pg\">p.326–341<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Physically stops him, declares she was wrong to accept his methods, and is brushed aside.<span class=\"pg\">p.326–328<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Reveals the plot and bounty to her and Ayanokōji; urges them to beware other first-year classes.<span class=\"pg\">p.328–341<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Directs open hatred at him — the White Room agent&#x27;s true motive remains hidden; she stays behind to explain, then leaves.<span class=\"pg\">p.341<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p290-1\">← Before: Ch.6: Mediating and revealing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p344-1\">→ After: Epilogue: Short story<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p344-1","v":"y2v1","y":2,"o":16,"k":"","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa epilogue  short story irons out the agreement with horikita  observes ayanokoji on the school grounds  approaches him  meets him","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p344-1\"><h3><span class=\"ttl\">Epilogue: Short story<\/span><span class=\"meta\">Y2V1 · p.344, 364–365<\/span><\/h3><p class=\"setup\">Irons out the agreement with Horikita. Observes Ayanokōji on the school grounds. Approaches him.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Meets him.<span class=\"pg\">p.344, 364–365<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p326-1\">← Before: Nanase stops Hōsen; reveals the 20-million bounty and her hatred<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p364-1\">→ After: Short story: &quot;What is Reflected in Her Eyes&quot;<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p364-1","v":"y2v1","y":2,"o":16,"k":"narration","w":"ayanokouji-kiyotaka housen-kazuomi nanase-tsubasa","q":"nanase tsubasa short story   what is reflected in her eyes  after leaving the dorm  spots ayanokoji approaching two class 1 a girls and decides to intercept him first  running to match his pace   good morning  ayanokouji senpai   i definitely think i managed a perfect smile   ayanokouji senpai s presence is unusually peculiar   i will force him to deepen his relationship with class 1 d   you can t judge people by their apperances  from her own viewpoint  deliberately engineers the chance morning encounter  judging ayanokoji an absentminded sharpened blade whose good or evil nature is all that matters to her  holds strongly to the belief that appearances can t tell a person s worth  the corpus prints  apperances  and notes his d class cooperation proposal is exactly what she d wanted   the white room agent manipulating the meeting  deliberately approaches him to draw him into class 1 d  he unexpectedly proposes the very cooperation she sought  she follows him to stop his outbursts  feeling powerless","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p364-1\"><h3><span class=\"ttl\">Short story: &quot;What is Reflected in Her Eyes&quot;<\/span><span class=\"meta\">Y2V1 · p.364–367<\/span><\/h3><p class=\"setup\">After leaving the dorm, spots Ayanokōji approaching two Class 1-A girls and decides to intercept him first, running to match his pace.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a><\/p><ul class=\"lines\"><li class=\"q narration\">&quot;Good morning, Ayanokouji-senpai.&quot;<span class=\"pg\">p.364<\/span><\/li><li class=\"q narration\">&quot;I definitely think I managed a perfect smile.&quot;<span class=\"pg\">p.365<\/span><\/li><li class=\"q narration\">&quot;Ayanokouji-senpai&#x27;s presence is unusually peculiar.&quot;<span class=\"pg\">p.365<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;I will force him to deepen his relationship with class 1-D&quot;<span class=\"pg\">p.366<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;You can&#x27;t judge people by their apperances.&quot;<span class=\"pg\">p.367<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> From her own viewpoint, deliberately engineers the chance morning encounter, judging Ayanokōji an absentminded sharpened blade whose good-or-evil nature is all that matters to her; holds strongly to the belief that appearances can&#x27;t tell a person&#x27;s worth (the corpus prints &quot;apperances&quot;) and notes his D-Class cooperation proposal is exactly what she&#x27;d wanted — the White Room agent manipulating the meeting.<span class=\"pg\">p.364–367<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Deliberately approaches him to draw him into Class 1-D; he unexpectedly proposes the very cooperation she sought.<span class=\"pg\">p.364–367<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> She follows him to stop his outbursts, feeling powerless.<span class=\"pg\">p.365<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p344-1\">← Before: Epilogue: Short story<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p368-1\">→ After: Short story: &quot;The Voice in My Heart&quot;<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p368-1","v":"y2v1","y":2,"o":16,"k":"narration","w":"ayanokouji-kiyotaka horikita-suzune nanase-tsubasa","q":"nanase tsubasa short story   the voice in my heart  after horikita leaves the library  probes ayanokoji about how he ll convince hosen  then turns the question on him   that  i don t have a problem answering that question but only if  if you can tell me about you   what  kind of person are you  senpai   what you want to know isn t about her relationship with me  it seems   yes  i think you are a wicked and a filthy human being  ayanokouji senpai   as far as i can see  you look like a regular human being  ayanokouji senpai  boldly voices her belief that he is a wicked  filthy human being yet looks like a regular human   testing him about his true nature  good or evil  retreats when she fears she s come too close  while noting he seemed to understand exactly what she wanted to ask  uses the masculine  boku   katakana  hinting at her link to him  presses him on what kind of person he is  he sees through her intended question  admires her and wishes to become as splendid as her by next year","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p368-1\"><h3><span class=\"ttl\">Short story: &quot;The Voice in My Heart&quot;<\/span><span class=\"meta\">Y2V1 · p.368–369<\/span><\/h3><p class=\"setup\">After Horikita leaves the library, probes Ayanokōji about how he&#x27;ll convince Hōsen, then turns the question on him.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q narration\">&quot;That… I don&#x27;t have a problem answering that question but only if, if you can tell me about you.&quot;<span class=\"pg\">p.368<\/span><\/li><li class=\"q narration\">&quot;What— kind of person are you, senpai?&quot;<span class=\"pg\">p.368<\/span><\/li><li class=\"q narration\">&quot;What you want to know isn&#x27;t about her relationship with me, it seems.&quot;<span class=\"pg\">p.369<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;Yes, I think you are a wicked and a filthy human being, Ayanokouji-senpai.&quot;<span class=\"pg\">p.369<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;As far as I can see, you look like a regular human being, Ayanokouji-senpai.&quot;<span class=\"pg\">p.369<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Boldly voices her belief that he is a wicked, filthy human being yet looks like a regular human — testing him about his true nature (good or evil); retreats when she fears she&#x27;s come too close, while noting he seemed to understand exactly what she wanted to ask; uses the masculine &quot;boku&quot; (katakana), hinting at her link to him.<span class=\"pg\">p.368–369<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Presses him on what kind of person he is; he sees through her intended question.<span class=\"pg\">p.368–369<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Admires her and wishes to become as splendid as her by next year.<span class=\"pg\">p.368<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p364-1\">← Before: Short story: &quot;What is Reflected in Her Eyes&quot;<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v2-p111-1","v":"y2v2","y":2,"o":17,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa nanase walks with ayanokoji to school she greets him on the way to school  apologizes for the expulsion attempt  and shares 1st year intelligence  the special exam is still active until the second semester  class 1 d placed third in their second exam  and hosen is now focused on fighting 2nd years   i ve always felt sorry for what i did to you  ayanokouji senpai   one boy dropped out of class c in the first year   you must not leave any regrets in your school life as well  ayanokouji senpai  mature and remorseful   she has shed her naivety and fits in well with the school  she walks with him and shares intelligence","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v2-p111-1\"><h3><span class=\"ttl\">Nanase walks with Ayanokōji to school<\/span><span class=\"meta\">Y2V2 · p.111–116<\/span><\/h3><p class=\"setup\">She greets him on the way to school, apologizes for the expulsion attempt, and shares 1st-year intelligence: the special exam is still active until the second semester, Class 1-D placed third in their second exam, and Hōsen is now focused on fighting 2nd years.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;I&#x27;ve always felt sorry for what I did to you, Ayanokouji-senpai.&quot;<span class=\"pg\">p.112<\/span><\/li><li class=\"q spoken\">&quot;One boy dropped out of Class C in the first year.&quot;<span class=\"pg\">p.114<\/span><\/li><li class=\"q spoken\">&quot;You must not leave any regrets in your school life as well, Ayanokouji-senpai&quot;<span class=\"pg\">p.116<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Mature and remorseful — she has shed her naivety and fits in well with the school.<span class=\"pg\">p.111–116<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She walks with him and shares intelligence.<span class=\"pg\">p.111–116<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v2-p336-1\">→ After: Tsukishiro reveals Nanase as the enforcer<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v2-p336-1","v":"y2v2","y":2,"o":17,"k":"narration","w":"tsukishiro ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa tsukishiro reveals nanase as the enforcer stands with tsukishiro as buses arrive  responding without emotion to his question about the late july heat  pressed to finally expel ayanokoji   yes  you are right    her emotionless reply  you re saying i should  expel ayanokouji kiyotaka   yes  i won t hesitate anymore  the white room enforcer whose left hand clenches as if brimming with natural power when tsukishiro names her   after his urging she resolves to stop hesitating and act in the island exam  tsukishiro calls her  nanase tsubasa san  her handler  pressures her to expel ayanokoji before his tenure ends and promises they ll return to their  previous life  her target  she agrees to act without hesitation","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v2-p336-1\"><h3><span class=\"ttl\">Tsukishiro reveals Nanase as the enforcer<\/span><span class=\"meta\">Y2V2 · p.336–337<\/span><\/h3><p class=\"setup\">Stands with Tsukishiro as buses arrive, responding without emotion to his question about the late July heat; pressed to finally expel Ayanokōji.<\/p><p class=\"with\">with <a href=\"tsukishiro.html\">Tsukishiro<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q narration\">&quot;Yes, you are right.&quot; — her emotionless reply<span class=\"pg\">p.336<\/span><\/li><li class=\"q narration\">&quot;You&#x27;re saying I should— expel Ayanokouji Kiyotaka?&quot;<span class=\"pg\">p.336<\/span><\/li><li class=\"q narration\">&quot;—Yes. I won&#x27;t hesitate anymore.&quot;<span class=\"pg\">p.337<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> The White Room enforcer whose left hand clenches as if brimming with natural power when Tsukishiro names her — after his urging she resolves to stop hesitating and act in the island exam; Tsukishiro calls her &quot;Nanase Tsubasa-san.&quot;<span class=\"pg\">p.336–337<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Her handler; pressures her to expel Ayanokōji before his tenure ends and promises they&#x27;ll return to their &quot;previous life.&quot;<span class=\"pg\">p.336–337<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Her target; she agrees to act without hesitation.<span class=\"pg\">p.336–337<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v2-p111-1\">← Before: Nanase walks with Ayanokōji to school<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p7-1","v":"y2v3","y":2,"o":18,"k":"","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa nanase s prologue monologue in her own voice she recalls the suicide of someone she admired  eiichiro  and vows to defeat ayanokoji kiyotaka for real  to send him back to the white room  her  true objective lies far beyond defeating him  this is nanase s interior monologue  her pov  no spoken line is quoted  determined and burdened by guilt   she fights under her own brand of justice  to defeat ayanokoji and send him back to the white room  her true objective lies beyond that  she has resolved to defeat him for real","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p7-1\"><h3><span class=\"ttl\">Nanase&#x27;s prologue monologue<\/span><span class=\"meta\">Y2V3 · p.7–8<\/span><\/h3><p class=\"setup\">In her own voice she recalls the suicide of someone she admired (Eiichirō) and vows to defeat Ayanokōji Kiyotaka for real, to send him back to the White Room; her &quot;true objective lies far beyond defeating him.&quot;<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> This is Nanase&#x27;s interior monologue (her POV); no spoken line is quoted.<span class=\"pg\">p.7–8<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Determined and burdened by guilt — she fights under her own brand of justice.<span class=\"pg\">p.7–8<\/span><\/li><li><span class=\"mlabel\">Goal<\/span> To defeat Ayanokōji and send him back to the White Room; her true objective lies beyond that.<span class=\"pg\">p.7–8<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She has resolved to defeat him for real.<span class=\"pg\">p.7–8<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p7-2\">→ After: Nanase&#x27;s monologue: resolving to defeat Ayanokōji for real<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p7-2","v":"y2v3","y":2,"o":18,"k":"narration","w":"ayanokouji-kiyotaka tsukishiro nanase-tsubasa","q":"nanase tsubasa nanase s monologue  resolving to defeat ayanokoji for real reflects on the shock of discovering the cruel reality about ayanokoji   the evening sun in an old apartment  a long shadow swinging  like the pendulum of a grandfather clock   that warm hand that would caress my head   that gentle smile that healed my soul   that sincere gaze that taught me admiration   that silent  blank expression that brought me to the edge of despair   and that s why   i  will   to send him back to the place he s meant to be   because  if i don t  there will surely be a second or even third victim that follows   after all  my true objective lies far beyond defeating him  cannot forgive  and cannot fight under a banner of  justice  with a  fragile heart    so she  as  i  distinct from the justice driven others  will defeat ayanokoji for real  to prevent further victims  her true objective lies beyond defeating him  she sees him standing before her  eyes fixed on her  and decides the time to act is now  her target  she is determined to end it on the island and send him  back to the place he s meant to be  implied   the  others  fight under their own justice  she fights with her own reason rooted in a personal loss","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p7-2\"><h3><span class=\"ttl\">Nanase&#x27;s monologue: resolving to defeat Ayanokōji for real<\/span><span class=\"meta\">Y2V3 · p.7–8<\/span><\/h3><p class=\"setup\">Reflects on the shock of discovering the cruel reality about Ayanokōji — the evening sun in an old apartment, a long shadow swinging &quot;like the pendulum of a grandfather clock.&quot;<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"tsukishiro.html\">Tsukishiro<\/a><\/p><ul class=\"lines\"><li class=\"q narration\">&quot;That warm hand that would caress my head.&quot;<span class=\"pg\">p.7<\/span><\/li><li class=\"q narration\">&quot;That gentle smile that healed my soul.&quot;<span class=\"pg\">p.7<\/span><\/li><li class=\"q narration\">&quot;That sincere gaze that taught me admiration.&quot;<span class=\"pg\">p.7<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;That silent, blank expression that brought me to the edge of despair.&quot;<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;And that&#x27;s why, 『I』 will.&quot;<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;To send him back to the place he&#x27;s meant to be.&quot;<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;Because, if I don&#x27;t, there will surely be a second or even third victim that follows.&quot;<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;after all, my true objective lies far beyond defeating him.&quot;<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Cannot forgive, and cannot fight under a banner of &quot;justice&quot; with a &quot;fragile heart&quot; — so she (as &quot;I,&quot; distinct from the justice-driven others) will defeat Ayanokōji for real, to prevent further victims; her true objective lies beyond defeating him; she sees him standing before her, eyes fixed on her, and decides the time to act is now.<span class=\"pg\">p.7–8<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Her target; she is determined to end it on the island and send him &quot;back to the place he&#x27;s meant to be.&quot;<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Implied — the &quot;others&quot; fight under their own justice; she fights with her own reason rooted in a personal loss.<span class=\"pg\">p.8<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p7-1\">← Before: Nanase&#x27;s prologue monologue<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p58-1\">→ After: Nanase meets Ayanokōji again<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p58-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa nanase meets ayanokoji again she meets ayanokoji at the first designated area  she has earned 3 points and he earned 2  they part ways   i think i m going to leave  it can t hurt to take a look around  independent and proactive   she scouts ahead  they compare points","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p58-1\"><h3><span class=\"ttl\">Nanase meets Ayanokōji again<\/span><span class=\"meta\">Y2V3 · p.58–59<\/span><\/h3><p class=\"setup\">She meets Ayanokōji at the first designated area; she has earned 3 points and he earned 2; they part ways.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;I think I&#x27;m going to leave. It can&#x27;t hurt to take a look around.&quot;<span class=\"pg\">p.59<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Independent and proactive — she scouts ahead.<span class=\"pg\">p.58–59<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> They compare points.<span class=\"pg\">p.58–59<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p7-2\">← Before: Nanase&#x27;s monologue: resolving to defeat Ayanokōji for real<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p75-1\">→ After: Nanase accompanies Ayanokōji<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p75-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa nanase accompanies ayanokoji she asks to accompany him  explaining her group s issue  he agrees   if it s not too much trouble  would you perhaps allow me to accompany you  proactive and strategic   she seeks out ayanokoji to avoid falling behind  she accompanies him","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p75-1\"><h3><span class=\"ttl\">Nanase accompanies Ayanokōji<\/span><span class=\"meta\">Y2V3 · p.75–88<\/span><\/h3><p class=\"setup\">She asks to accompany him, explaining her group&#x27;s issue; he agrees.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;If it&#x27;s not too much trouble, would you perhaps allow me to accompany you?&quot;<span class=\"pg\">p.79<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Proactive and strategic — she seeks out Ayanokōji to avoid falling behind.<span class=\"pg\">p.75–88<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She accompanies him.<span class=\"pg\">p.75–88<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p58-1\">← Before: Nanase meets Ayanokōji again<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p78-1\">→ After: Nanase tags along: &quot;travel companion&quot;<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p78-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka housen-kazuomi amasawa-ichika nanase-tsubasa","q":"nanase tsubasa nanase tags along   travel companion  appears alone again at his break   the third time they ve crossed paths in six designated areas  hints they may share a table   ayanokoji senpai  it seems we meet again   if it s not too much trouble  would you perhaps allow me to accompany you for a while   both hosen kun and amasawa san felt that we would be better off if we all acted independently  so everything more or less fell apart   i would be perfectly fine with taking the back seat in that regard   i m fairly confident in my stamina   you re not uncertain because you think i might hold you back  it s more that you re not able to trust me  isn t it   once again  just to reiterate  please disregard my presence and choose what you truly believe to be the most ideal route   it seems i have the same table as senpai after all  polite  perceptive and calculating   asks to join claiming her group dissolved into independent action  defers all bonuses tasks and route choices to him  sees through his concern for sudo s group and discerns ike is unwell  her tablet confirms the same table  she repeatedly insists he ignore her so as not to distort his decisions   the white room agent deliberately embedding herself with her target  travels with him  he suspects her motives but allows it  using it to gauge her  says he and amasawa chose independent action  likewise","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p78-1\"><h3><span class=\"ttl\">Nanase tags along: &quot;travel companion&quot;<\/span><span class=\"meta\">Y2V3 · p.78–96<\/span><\/h3><p class=\"setup\">Appears alone again at his break — the third time they&#x27;ve crossed paths in six designated areas; hints they may share a Table.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"amasawa-ichika.html\">Amasawa Ichika<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Ayanokōji-senpai, it seems we meet again.&quot;<span class=\"pg\">p.78<\/span><\/li><li class=\"q spoken\">&quot;If it&#x27;s not too much trouble, would you perhaps allow me to accompany you for a while?&quot;<span class=\"pg\">p.79<\/span><\/li><li class=\"q spoken\">&quot;Both Hōsen-kun and Amasawa-san felt that we would be better off if we all acted independently, so everything more or less fell apart.&quot;<span class=\"pg\">p.79<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I would be perfectly fine with taking the back seat in that regard,&quot;<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;m fairly confident in my stamina.&quot;<span class=\"pg\">p.81<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You&#x27;re not uncertain because you think I might hold you back, it&#x27;s more that you&#x27;re not able to trust me, isn&#x27;t it?&quot;<span class=\"pg\">p.81<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Once again, just to reiterate, please disregard my presence and choose what you truly believe to be the most ideal route.&quot;<span class=\"pg\">p.93<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It seems I have the same Table as Senpai after all.&quot;<span class=\"pg\">p.94<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Polite, perceptive and calculating — asks to join claiming her group dissolved into independent action, defers all bonuses/Tasks and route choices to him, sees through his concern for Sudō&#x27;s group and discerns Ike is unwell; her tablet confirms the same Table; she repeatedly insists he ignore her so as not to distort his decisions — the White Room agent deliberately embedding herself with her target.<span class=\"pg\">p.78–96<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Travels with him; he suspects her motives but allows it, using it to gauge her.<span class=\"pg\">p.78–96<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Says he and Amasawa chose independent action.<span class=\"pg\">p.79<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> Likewise.<span class=\"pg\">p.79<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p75-1\">← Before: Nanase accompanies Ayanokōji<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p110-1\">→ After: Nanase accompanies Ayanokōji on day 3<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p110-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa nanase accompanies ayanokoji on day 3 she wakes ayanokoji and discusses ike s situation  they head out with sudo and hondo  she participates in the beach flags task while ayanokoji watches  she walks with him and discusses his solo strategy and water plans   ayanokoji senpai  why did you decide to take part in the exam alone  curious and concerned   she asks about his solo approach  she accompanies him","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p110-1\"><h3><span class=\"ttl\">Nanase accompanies Ayanokōji on day 3<\/span><span class=\"meta\">Y2V3 · p.110–151<\/span><\/h3><p class=\"setup\">She wakes Ayanokōji and discusses Ike&#x27;s situation; they head out with Sudō and Hondō. She participates in the Beach Flags Task while Ayanokōji watches. She walks with him and discusses his solo strategy and water plans.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Ayanokōji-senpai, why did you decide to take part in the exam alone?&quot;<span class=\"pg\">p.135<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Curious and concerned — she asks about his solo approach.<span class=\"pg\">p.110–151<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She accompanies him.<span class=\"pg\">p.110–151<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p78-1\">← Before: Nanase tags along: &quot;travel companion&quot;<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p110-2\">→ After: Nanase: worry, Beach Flags victory, and mutual probing<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p110-2","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka ike-kanji housen-kazuomi amasawa-ichika nanase-tsubasa","q":"nanase tsubasa nanase  worry  beach flags victory  and mutual probing wakes ayanokoji early  worried she said too much to ike the night before   it s about ike senpai  do you think i said a little too much last night   thanks to you  ike s managed to get back on his feet   i feel like ike senpai is in a sort of precarious position right now   if senpai can t participate then i ll sit this one out as well   a reason  from what i ve seen of beach flags on tv  girls usually compete wearing swimsuits like this  right   thank you very much  i managed to get through it somehow   seeing you stare at me so closely like that  it s  well  it s a little unsettling  you know   ayanokoji senpai  why did you decide to take part in the exam alone   back when you faced off against hosen kun  your movements were different from those of a normal high school student   even so  it s not like it s impossible for me to win either   have you always been like that    about his disposition  in the past  i get the sense that i used to smile more   an incident took place that i believe changed me forever  anxious about ike  protective  and a formidable athlete   in a blue green bikini she wins beach flags in perfect sync with the gun with energy to spare  true ability beyond oaa b  cleverly probes ayanokoji s white room nature  noting his movements are those of no normal high school student  while deflecting about her own middle school  incident  that changed her from light to dark   the white room agent testing her target  mutual probing   she notes his unusual movements  he notes a white room student wouldn t have middle school  she hints at a past  incident  worried her words to him might backfire  credits ayanokoji with helping him  take a stand  says her group  hosen amasawa  is earning points from tasks  likewise","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p110-2\"><h3><span class=\"ttl\">Nanase: worry, Beach Flags victory, and mutual probing<\/span><span class=\"meta\">Y2V3 · p.110–138<\/span><\/h3><p class=\"setup\">Wakes Ayanokōji early, worried she said too much to Ike the night before.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"ike-kanji.html\">Ike Kanji<\/a> · <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"amasawa-ichika.html\">Amasawa Ichika<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;It&#x27;s about Ike-senpai. Do you think I said a little too much last night…?&quot;<span class=\"pg\">p.110<\/span><\/li><li class=\"q spoken\">&quot;Thanks to you, Ike&#x27;s managed to get back on his feet.&quot;<span class=\"pg\">p.110<\/span><\/li><li class=\"q spoken\">&quot;I feel like Ike-senpai is in a sort-of precarious position right now.&quot;<span class=\"pg\">p.111<\/span><\/li><\/ul><details class=\"more\"><summary>15 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;If Senpai can&#x27;t participate then I&#x27;ll sit this one out as well.&quot;<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;A reason? From what I&#x27;ve seen of Beach Flags on TV, girls usually compete wearing swimsuits like this, right?&quot;<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Thank you very much. I managed to get through it somehow.&quot;<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Seeing you stare at me so closely like that, it&#x27;s… well, it&#x27;s a little unsettling, you know…?&quot;<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Ayanokōji-senpai, why did you decide to take part in the exam alone?&quot;<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Back when you faced off against Hōsen-kun, your movements were different from those of a normal high school student.&quot;<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Even so, it&#x27;s not like it&#x27;s impossible for me to win either.&quot;<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Have you always been like that?&quot; — about his disposition<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;In the past─ I get the sense that I used to smile more.&quot;<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;an incident took place that I believe changed me forever…&quot;<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Anxious about Ike, protective, and a formidable athlete — in a blue-green bikini she wins Beach Flags in perfect sync with the gun with energy to spare (true ability beyond OAA B+); cleverly probes Ayanokōji&#x27;s White Room nature (noting his movements are those of no normal high school student) while deflecting about her own middle-school &quot;incident&quot; that changed her from light to dark — the White Room agent testing her target.<span class=\"pg\">p.110–138<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Mutual probing — she notes his unusual movements; he notes a White Room student wouldn&#x27;t have middle school; she hints at a past &quot;incident.&quot;<span class=\"pg\">p.135–138<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Worried her words to him might backfire; credits Ayanokōji with helping him &quot;take a stand.&quot;<span class=\"pg\">p.110–111<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Says her group (Hōsen/Amasawa) is earning points from Tasks.<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> Likewise.<span class=\"pg\">p.138<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p110-1\">← Before: Nanase accompanies Ayanokōji on day 3<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p164-1\">→ After: Nanase helps in the emergency<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p164-1","v":"y2v3","y":2,"o":18,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa nanase helps in the emergency she helps wake the group and search for shinohara  she takes a flashlight and follows ayanokoji  helpful and alert   she assists in the emergency search","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p164-1\"><h3><span class=\"ttl\">Nanase helps in the emergency<\/span><span class=\"meta\">Y2V3 · p.164–186<\/span><\/h3><p class=\"setup\">She helps wake the group and search for Shinohara; she takes a flashlight and follows Ayanokōji.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Helpful and alert — she assists in the emergency search.<span class=\"pg\">p.164–186<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p110-2\">← Before: Nanase: worry, Beach Flags victory, and mutual probing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p164-2\">→ After: Nanase in the cliff crisis and rescue planning<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p164-2","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka shinohara ike-kanji nanase-tsubasa","q":"nanase tsubasa nanase in the cliff crisis and rescue planning joins the pre dawn search  carries a flashlight and later takes charge of leading the group back   i wasn t able to see you and ike senpai anymore so i    she came to find them  i m glad that you managed to find shinohara senpai safe and sound   isn t it strange that komiya senpai didn t notice anybody   as for me  if i were to attack komiya senpai and kinoshita senpai  i don t think it would be impossible   it s possible to lighten the burden by bunkering down near the starting area   rather than going through the effort of forming another group  it may very well be more realistic for her to prioritize accumulating points  composed and insightful   points out the  out of place  vibration that leads to finding people  analyzes shinohara s testimony with ayanokoji  reaching the same skeptical conclusion  holds his tablet  comes to find them  proposes shinohara bunker near the harbor to survive  and advises against trying to merge into another group   all while monitoring ayanokoji  reasons with him about the  culprit  holds his tablet  and discusses the rescue plan  proposes the harbor survival strategy to save her  comes looking for him and shinohara","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p164-2\"><h3><span class=\"ttl\">Nanase in the cliff crisis and rescue planning<\/span><span class=\"meta\">Y2V3 · p.164–207<\/span><\/h3><p class=\"setup\">Joins the pre-dawn search; carries a flashlight and later takes charge of leading the group back.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"shinohara.html\">Shinohara<\/a> · <a href=\"ike-kanji.html\">Ike Kanji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;I wasn&#x27;t able to see you and Ike-senpai anymore so I─&quot; — she came to find them<span class=\"pg\">p.189<\/span><\/li><li class=\"q spoken\">&quot;I&#x27;m glad that you managed to find Shinohara-senpai safe and sound.&quot;<span class=\"pg\">p.189<\/span><\/li><li class=\"q spoken\">&quot;isn&#x27;t it strange that Komiya-senpai didn&#x27;t notice anybody?&quot;<span class=\"pg\">p.190<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;As for me… If I were to attack Komiya-senpai and Kinoshita-senpai… I don&#x27;t think it would be impossible.&quot;<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It&#x27;s possible to lighten the burden by bunkering down near the starting area.&quot;<span class=\"pg\">p.200<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;rather than going through the effort of forming another group, it may very well be more realistic for her to prioritize accumulating points.&quot;<span class=\"pg\">p.205<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Composed and insightful — points out the &quot;out-of-place&quot; vibration that leads to finding people, analyzes Shinohara&#x27;s testimony with Ayanokōji (reaching the same skeptical conclusion), holds his tablet, comes to find them, proposes Shinohara bunker near the harbor to survive, and advises against trying to merge into another group — all while monitoring Ayanokōji.<span class=\"pg\">p.164–207<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Reasons with him about the &quot;culprit,&quot; holds his tablet, and discusses the rescue plan.<span class=\"pg\">p.190–205<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shinohara<\/b> Proposes the harbor-survival strategy to save her.<span class=\"pg\">p.200<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Comes looking for him and Shinohara.<span class=\"pg\">p.189<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p164-1\">← Before: Nanase helps in the emergency<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p260-1\">→ After: Nanase&#x27;s cliff struggle and her strange air<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p260-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa nanase s cliff struggle and her strange air  i  i can do this   oww  that hurt   i i can do it   please  don t mind me  i ve made the choice to follow after you of my own volition  ayanokoji senpai   i  i can t do that senpai  i promised you that i wouldn t get in your way back when i asked to accompany you   t thank goodness   senpai  do you enjoy it  this school   while it feels like graduation is a long ways away  it ll probably be here in the blink of an eye  falls while tying up her hair to climb  but insists on following ayanokoji  exhausted  she accepts his hand  afterward she asks if he enjoys the school and speaks of living without regrets   her bearing briefly resembles the nanase he first met  a faint  unsettling change ayanokoji notes  follows him up the cliff  her  loyal dog  devotion and subtle shift in demeanor hint at her true nature","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p260-1\"><h3><span class=\"ttl\">Nanase&#x27;s cliff struggle and her strange air<\/span><span class=\"meta\">Y2V3 · p.260–266<\/span><\/h3><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;I… I can do this!&quot;<span class=\"pg\">p.261<\/span><\/li><li class=\"q spoken\">&quot;Oww, that hurt…!&quot;<span class=\"pg\">p.261<\/span><\/li><li class=\"q spoken\">&quot;I-I can do it!&quot;<span class=\"pg\">p.262<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Please… don&#x27;t mind me. I&#x27;ve made the choice to follow after you of my own volition, Ayanokōji-senpai…!&quot;<span class=\"pg\">p.263<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I, I can&#x27;t do that Senpai. I promised you that I wouldn&#x27;t get in your way back when I asked to accompany you.&quot;<span class=\"pg\">p.264<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;T-thank goodness…!&quot;<span class=\"pg\">p.265<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Senpai, do you enjoy it? This school?&quot;<span class=\"pg\">p.265<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;While it feels like graduation is a long ways away, it&#x27;ll probably be here in the blink of an eye.&quot;<span class=\"pg\">p.265<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Falls while tying up her hair to climb, but insists on following Ayanokōji; exhausted, she accepts his hand; afterward she asks if he enjoys the school and speaks of living without regrets — her bearing briefly resembles the Nanase he first met, a faint, unsettling change Ayanokōji notes.<span class=\"pg\">p.260–266<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Follows him up the cliff; her &quot;loyal dog&quot; devotion and subtle shift in demeanor hint at her true nature.<span class=\"pg\">p.260–266<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p164-2\">← Before: Nanase in the cliff crisis and rescue planning<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p287-1\">→ After: Nanase&#x27;s trap: the White Room agent reveals herself and attacks<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p287-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka tsukishiro matsuo-eiichiro nanase-tsubasa","q":"nanase tsubasa nanase s trap  the white room agent reveals herself and attacks on the mountain path  stops ayanokoji  sets down her bag  and reveals she lured him to northern d3   not e2   ayanokoji senpai  i have something i d like to ask you   i m afraid you won t be reaching area e2 today  senpai   the reason i wanted to head up the mountain was to lure you here  senpai   but  ayanokoji senpai  i don t think you re someone who belongs at this school   it s because you re from the white room   as you may have already guessed  i enrolled here in this school under acting director tsukishiro s orders   i m going to knock you out here and injure you  setting off your emergency alert in the process   therefore i will  right here  right now   i came back from  that place  in order to put a stop to you   i m not nanase  the one standing here before you right now is  matsuo eiichiro   aaaaaaaahhhhhhh  the white room enforcer sent by tsukishiro to get ayanokoji expelled   lures him to a secluded spot to knock him out and trigger his emergency alert  framing him like komiya kinoshita  after praising his abilities  she attacks  and when her  watashi  persona falters  she switches to the aggressive  boku  persona of  matsuo eiichiro   the son of a man killed by atsuomi    faster karate strikes fueled by hatred  ayanokoji dismantles the persona as self deception  she s too nonviolent to truly fight  and she collapses in tears  defeated without ever landing a hit  her target  she confesses her mission and fights him  but cannot bring herself to truly hurt him  her handler who ordered the expulsion and would cover it up  the persona she impersonates   a real boy whose father was connected to atsuomi","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p287-1\"><h3><span class=\"ttl\">Nanase&#x27;s trap: the White Room agent reveals herself and attacks<\/span><span class=\"meta\">Y2V3 · p.287–304<\/span><\/h3><p class=\"setup\">On the mountain path, stops Ayanokōji, sets down her bag, and reveals she lured him to northern D3 — not E2.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"tsukishiro.html\">Tsukishiro<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Ayanokōji-senpai, I have something I&#x27;d like to ask you.&quot;<span class=\"pg\">p.287<\/span><\/li><li class=\"q spoken\">&quot;I&#x27;m afraid you won&#x27;t be reaching area E2 today, Senpai.&quot;<span class=\"pg\">p.288<\/span><\/li><li class=\"q spoken\">&quot;The reason I wanted to head up the mountain was to lure you here, Senpai.&quot;<span class=\"pg\">p.288<\/span><\/li><\/ul><details class=\"more\"><summary>12 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;But, Ayanokōji-senpai, I don&#x27;t think you&#x27;re someone who belongs at this school.&quot;<span class=\"pg\">p.288<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It&#x27;s because you&#x27;re from the White Room.&quot;<span class=\"pg\">p.289<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;As you may have already guessed, I enrolled here in this school under Acting Director Tsukishiro&#x27;s orders.&quot;<span class=\"pg\">p.289<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;m going to knock you out here and injure you, setting off your Emergency Alert in the process.&quot;<span class=\"pg\">p.289<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Therefore…『I』will. Right here, right now.&quot;<span class=\"pg\">p.296<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;『I』came back from &#x27;that place&#x27; in order to put a stop to you.&quot;<span class=\"pg\">p.296<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;『I&#x27;m』not Nanase. The one standing here before you right now is… Matsuo Eiichiro.&quot;<span class=\"pg\">p.299<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;AAAAAAAAHHHHHHH!!!&quot;<span class=\"pg\">p.302<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> The White Room enforcer sent by Tsukishiro to get Ayanokōji expelled — lures him to a secluded spot to knock him out and trigger his Emergency Alert (framing him like Komiya/Kinoshita); after praising his abilities, she attacks, and when her &quot;Watashi&quot; persona falters, she switches to the aggressive &quot;Boku&quot; persona of &quot;Matsuo Eiichiro&quot; (the son of a man killed by Atsuomi) — faster karate strikes fueled by hatred. Ayanokōji dismantles the persona as self-deception (she&#x27;s too nonviolent to truly fight), and she collapses in tears, defeated without ever landing a hit.<span class=\"pg\">p.287–304<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Her target; she confesses her mission and fights him, but cannot bring herself to truly hurt him.<span class=\"pg\">p.287–304<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Her handler who ordered the expulsion and would cover it up.<span class=\"pg\">p.289<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">matsuo-eiichiro<\/b> The persona she impersonates — a real boy whose father was connected to Atsuomi.<span class=\"pg\">p.299<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p260-1\">← Before: Nanase&#x27;s cliff struggle and her strange air<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p347-1\">→ After: Nanase&#x27;s motive; accepting Ayanokōji&#x27;s hand<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p347-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka tsukishiro nanase-tsubasa","q":"nanase tsubasa nanase s motive  accepting ayanokoji s hand in the rain  defeated  admits her loss and explains why she targeted him   it s my loss  ayanokoji senpai   yes  it seems that  despite my best efforts  it truly isn t possible for me to beat you senpai   i  i enrolled in this school because i wanted to avenge my childhood friend   even after he was kicked out of his home  eiichiro kun said he wouldn t give up until the very end   earlier this year  on the evening of february 14th  i paid a visit to eiichiro kun s apartment   if i could successfully get you expelled  he promised to let me meet your father  senpai   i knew that you weren t the one at fault  ayanokoji senpai  but  i wanted  no  needed someone to take it out on   i  i don t know how i can face you anymore  senpai  i m so  so sorry   i ve failed to carry out the acting director s orders  there s no point in me staying here anymore   it s a promise  driven by grief and vindication   her childhood friend eiichiro  the butler s son  was ruined by atsuomi s schemes  his father self immolated  and eiichiro took his own life  tsukishiro exploited this  promising her a meeting with atsuomi if she expelled ayanokoji  her contradictory behavior  helping him while trying to expel him  came from not truly believing in her mission  ashamed  she wanted to drop out  but accepts ayanokoji s hand and promise to cooperate   finally meeting his eyes  confesses her vendetta  is forgiven  and becomes his ally  manipulated her with the promise of meeting atsuomi  eiichiro s father  the matsuo butler who served atsuomi  burned himself to death   that man    atsuomi","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p347-1\"><h3><span class=\"ttl\">Nanase&#x27;s motive; accepting Ayanokōji&#x27;s hand<\/span><span class=\"meta\">Y2V3 · p.347–353<\/span><\/h3><p class=\"setup\">In the rain, defeated, admits her loss and explains why she targeted him.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"tsukishiro.html\">Tsukishiro<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;It&#x27;s my loss… Ayanokōji-senpai.&quot;<span class=\"pg\">p.347<\/span><\/li><li class=\"q spoken\">&quot;Yes. It seems that, despite my best efforts, it truly isn&#x27;t possible for me to beat you Senpai.&quot;<span class=\"pg\">p.347<\/span><\/li><li class=\"q spoken\">&quot;I… I enrolled in this school because I wanted to avenge my childhood friend.&quot;<span class=\"pg\">p.347<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Even after he was kicked out of his home, Eiichiro-kun said he wouldn&#x27;t give up until the very end.&quot;<span class=\"pg\">p.348<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Earlier this year, on the evening of February 14th, I paid a visit to Eiichiro-kun&#x27;s apartment.&quot;<span class=\"pg\">p.349<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;If I could successfully get you expelled, he promised to let me meet your father, Senpai.&quot;<span class=\"pg\">p.350<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I knew that you weren&#x27;t the one at fault, Ayanokōji-senpai, but… I wanted… no, needed someone to take it out on…&quot;<span class=\"pg\">p.350<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I… I don&#x27;t know how I can face you anymore, Senpai… I&#x27;m so, so sorry…&quot;<span class=\"pg\">p.351<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;ve failed to carry out the Acting Director&#x27;s orders. There&#x27;s no point in me staying here anymore.&quot;<span class=\"pg\">p.351<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;─It&#x27;s a promise.&quot;<span class=\"pg\">p.352<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Driven by grief and vindication — her childhood friend Eiichiro (the butler&#x27;s son) was ruined by Atsuomi&#x27;s schemes, his father self-immolated, and Eiichiro took his own life; Tsukishiro exploited this, promising her a meeting with Atsuomi if she expelled Ayanokōji; her contradictory behavior (helping him while trying to expel him) came from not truly believing in her mission; ashamed, she wanted to drop out, but accepts Ayanokōji&#x27;s hand and promise to cooperate — finally meeting his eyes.<span class=\"pg\">p.347–353<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Confesses her vendetta, is forgiven, and becomes his ally.<span class=\"pg\">p.347–353<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Manipulated her with the promise of meeting Atsuomi.<span class=\"pg\">p.349–350<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Eiichiro&#x27;s father (the Matsuo butler who served Atsuomi) burned himself to death; &quot;that man&quot; = Atsuomi.<span class=\"pg\">p.348<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p287-1\">← Before: Nanase&#x27;s trap: the White Room agent reveals herself and attacks<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p360-1\">→ After: Short story: &quot;Unfathomable&quot; — the cliff climb from her POV<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p360-1","v":"y2v3","y":2,"o":18,"k":"narration","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa short story   unfathomable    the cliff climb from her pov from her own pov  reflects that her belief in equal stamina with ayanokoji was naive   he clears obstacles at 50 60  capacity while she struggles  and she fears falling too far behind   don t  mind me  i will  catch up to you  at my own pace   retiring will be the least of your worries if you fall from here    ayanokoji  n no  i won t have it   it would leave a bad aftertaste if i went ahead and you hurt yourself    ayanokoji  no  this is the first time i m moving up like this    ayanokoji grudgingly accepts his hand after he descends to help   moved that he offers kindness of his own accord  realizes he possesses  unfathomable abilities  and is  not normal  reaffirming her goal to defeat him and drag out  that person   matsuo    the reason she came to this school  her target and reluctant climbing partner  she s awed by his effortless strength and resolves to defeat him","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p360-1\"><h3><span class=\"ttl\">Short story: &quot;Unfathomable&quot; — the cliff climb from her POV<\/span><span class=\"meta\">Y2V3 · p.360–362<\/span><\/h3><p class=\"setup\">From her own POV, reflects that her belief in equal stamina with Ayanokōji was naive — he clears obstacles at 50–60% capacity while she struggles, and she fears falling too far behind.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q narration\">&quot;Don&#x27;t… mind me. I will, catch up to you, at my own pace…!&quot;<span class=\"pg\">p.360<\/span><\/li><li class=\"q narration\">&quot;Retiring will be the least of your worries if you fall from here.&quot; — Ayanokōji<span class=\"pg\">p.360<\/span><\/li><li class=\"q narration\">&quot;N-no, I won&#x27;t have it.&quot;<span class=\"pg\">p.361<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;It would leave a bad aftertaste if I went ahead and you hurt yourself.&quot; — Ayanokōji<span class=\"pg\">p.361<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;No, this is the first time I&#x27;m moving up like this.&quot; — Ayanokōji<span class=\"pg\">p.361<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Grudgingly accepts his hand after he descends to help — moved that he offers kindness of his own accord; realizes he possesses &quot;unfathomable abilities&quot; and is &quot;not normal,&quot; reaffirming her goal to defeat him and drag out &quot;that person&quot; (Matsuo) — the reason she came to this school.<span class=\"pg\">p.360–362<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Her target and reluctant climbing partner; she&#x27;s awed by his effortless strength and resolves to defeat him.<span class=\"pg\">p.360–362<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p347-1\">← Before: Nanase&#x27;s motive; accepting Ayanokōji&#x27;s hand<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p365-1\">→ After: Tapestry SS: &quot;What Could Be Seen From that Back&quot; — Beach Flags from her POV<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p365-1","v":"y2v3","y":2,"o":18,"k":"narration","w":"ayanokouji-kiyotaka tokunaga nanase-tsubasa","q":"nanase tsubasa tapestry ss   what could be seen from that back    beach flags from her pov from her own pov  lies prone for the beach flags final against third year tokunaga  aware ayanokoji is watching   fuu   what a terrifying 1st year  it s my loss    tokunaga  i looked at the oaa app for any upperclassmen i had to be wary of when preparing for this special exam   thank you so much  i managed to win somehow  goes  all out  despite the demerit of showing her abilities  because she feels she must display full power at all times  wins decisively via flawless timing  synced to the pistol  and preparation  studied tokunaga s oaa  then accepts the congratulations  watches her victory  she s conscious of performing for him  the third year opponent she studied and defeated","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p365-1\"><h3><span class=\"ttl\">Tapestry SS: &quot;What Could Be Seen From that Back&quot; — Beach Flags from her POV<\/span><span class=\"meta\">Y2V3 · p.365–366<\/span><\/h3><p class=\"setup\">From her own POV, lies prone for the Beach Flags final against third-year Tokunaga, aware Ayanokōji is watching.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"index.html#tokunaga\">Tokunaga<\/a><\/p><ul class=\"lines\"><li class=\"q narration\">&quot;Fuu…&quot;<span class=\"pg\">p.365<\/span><\/li><li class=\"q narration\">&quot;What a terrifying 1st year. It&#x27;s my loss.&quot; — Tokunaga<span class=\"pg\">p.366<\/span><\/li><li class=\"q narration\">&quot;I looked at the OAA app for any upperclassmen I had to be wary of when preparing for this special exam.&quot;<span class=\"pg\">p.366<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;Thank you so much. I managed to win somehow.&quot;<span class=\"pg\">p.366<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Goes &quot;all out&quot; despite the demerit of showing her abilities, because she feels she must display full power at all times; wins decisively via flawless timing (synced to the pistol) and preparation (studied Tokunaga&#x27;s OAA), then accepts the congratulations.<span class=\"pg\">p.365–366<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Watches her victory; she&#x27;s conscious of performing for him.<span class=\"pg\">p.365–366<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tokunaga<\/b> The third-year opponent she studied and defeated.<span class=\"pg\">p.366<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p360-1\">← Before: Short story: &quot;Unfathomable&quot; — the cliff climb from her POV<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4-p8-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ayanokouji-kiyotaka amasawa-ichika nanase-tsubasa","q":"nanase tsubasa nanase guards ayanokoji  accuses amasawa  please get behind me  senpai   you  cannot be trusted   please don t listen to her  she s dangerous   while you were gone  i noticed that someone had been watching us from nearby  so i tried chasing after them   back then  the one watching us from the shadows was you  wasn t it amasawa san   you also hurt komiya senpai and kinoshita senpai  didn t you   i don t believe you  not at all   what s with this  nanase chan    amasawa  nanase responds  you were about to lay your hands on ayanokoji senpai  weren t you   senpai  let s do a gps search right now  fiercely protective of ayanokoji  having become his ally  steps in front of him and grabs amasawa s arm  correctly identifies amasawa as the earlier watcher  saw her hair  and suspects her of the cliff attack  though ayanokoji notes the evidence is only circumstantial  remains  loyal dog  devoted to him  now his ally   guards him from amasawa  accuses her of watching them and pushing komiya kinoshita  sharp  suspicious exchanges","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4-p8-1\"><h3><span class=\"ttl\">Nanase guards Ayanokōji; accuses Amasawa<\/span><span class=\"meta\">Y2V4 · p.8–26<\/span><\/h3><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"amasawa-ichika.html\">Amasawa Ichika<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Please get behind me, Senpai.&quot;<span class=\"pg\">p.9<\/span><\/li><li class=\"q spoken\">&quot;You─ cannot be trusted.&quot;<span class=\"pg\">p.9<\/span><\/li><li class=\"q spoken\">&quot;Please don&#x27;t listen to her, she&#x27;s dangerous.&quot;<span class=\"pg\">p.10<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;While you were gone, I noticed that someone had been watching us from nearby, so I tried chasing after them.&quot;<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Back then, the one watching us from the shadows was you, wasn&#x27;t it Amasawa-san?&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You also hurt Komiya-senpai and Kinoshita-senpai, didn&#x27;t you?&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I don&#x27;t believe you. Not at all.&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;What&#x27;s with this, Nanase-chan?&quot; — Amasawa; Nanase responds<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You were about to lay your hands on Ayanokōji-senpai, weren&#x27;t you?&quot;<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Senpai, let&#x27;s do a GPS Search right now!&quot;<span class=\"pg\">p.25<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Fiercely protective of Ayanokōji (having become his ally), steps in front of him and grabs Amasawa&#x27;s arm; correctly identifies Amasawa as the earlier watcher (saw her hair) and suspects her of the cliff attack, though Ayanokōji notes the evidence is only circumstantial; remains &quot;loyal dog&quot; devoted to him.<span class=\"pg\">p.8–26<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Now his ally — guards him from Amasawa.<span class=\"pg\">p.8–26<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> Accuses her of watching them and pushing Komiya/Kinoshita; sharp, suspicious exchanges.<span class=\"pg\">p.9–25<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p120-1\">→ After: Nanase&#x27;s midnight warning about the day-12 plot<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4-p120-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ayanokouji-kiyotaka housen-kazuomi tsubaki-sakurako nanase-tsubasa","q":"nanase tsubasa nanase s midnight warning about the day 12 plot  it s me  nanase   i m fine  i was in i9 like you  in fact  i even saw you from afar at night  but since i was working with housen kun  so i decided to avoid contact   housen kun told me that on the twelfth day  the first years will make a great play on ayanokouji senpai   i don t know  but tsubaki was the main person i spoke to on the walkie talkie   yes  i ll let you know if there is more important news  risks sneaking to his tent at 2 30 a m  terrified  to pass on intelligence   the first years  led by tsubaki via walkie talkie  plan to force his withdrawal on day twelve  explains the errand boy contact and hosen s feigned cooperation  agrees to keep him informed but is told to stop helping him  warns him of the plot at personal risk  he sends her away so she won t be exposed  only pretending to cooperate with the first years  hosen told her about the day 12 plan  the main contact on the walkie talkie","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4-p120-1\"><h3><span class=\"ttl\">Nanase&#x27;s midnight warning about the day-12 plot<\/span><span class=\"meta\">Y2V4 · p.120–122<\/span><\/h3><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"tsubaki-sakurako.html\">Tsubaki Sakurako<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;It&#x27;s me, Nanase.&quot;<span class=\"pg\">p.120<\/span><\/li><li class=\"q spoken\">&quot;I&#x27;m fine; I was in I9 like you. In fact, I even saw you from afar at night, but since I was working with Housen-kun, so I decided to avoid contact.&quot;<span class=\"pg\">p.120<\/span><\/li><li class=\"q spoken\">&quot;Housen-kun told me that on the twelfth day, the first years will make a great play on Ayanokouji-senpai.&quot;<span class=\"pg\">p.120<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I don&#x27;t know, but Tsubaki was the main person I spoke to on the walkie-talkie.&quot;<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Yes, I&#x27;ll let you know if there is more important news.&quot;<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Risks sneaking to his tent at 2:30 a.m., terrified, to pass on intelligence — the first-years (led by Tsubaki via walkie-talkie) plan to force his withdrawal on day twelve; explains the errand-boy contact and Hōsen&#x27;s feigned cooperation; agrees to keep him informed but is told to stop helping him.<span class=\"pg\">p.120–122<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Warns him of the plot at personal risk; he sends her away so she won&#x27;t be exposed.<span class=\"pg\">p.120–122<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Only pretending to cooperate with the first-years; Hōsen told her about the day-12 plan.<span class=\"pg\">p.120–121<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsubaki Sakurako<\/b> The main contact on the walkie-talkie.<span class=\"pg\">p.121<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p8-1\">← Before: Nanase guards Ayanokōji; accuses Amasawa<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4_5-p182-1","v":"y2v4.5","y":2,"o":20,"k":"spoken","w":"ryuuen-kakeru utomiya-riku ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa nanase and ryuen interrogate kurachi  the cliff attacker  ryuen  investigating who pushed komiya  stops nanase during the treasure hunt  she agrees to help question kurachi naohiro  the first year who attacked ayanokoji on day seven   nanase tsubasa  right   tell me why you were targeting ayanokoji senpai during the uninhabited island exam   is urgently trying to find the culprit who almost attacked ayanokoji senpai   i was told i d be given money if i attacked ayanokoji senpai   give me time  of course  i don t mean for free  deftly interrogates kurachi using the threat of hosen s fists  plus ryuen behind her  learns utomiya riku paid him  anonymously  before the exam  to  pretend  to attack ayanokoji  brokers a deal with ryuen   she ll reveal a witness in komiya s case if he doesn t contact utomiya yet  works with him  reluctantly  to find the attacker  he wants to confront utomiya  she negotiates delay  revealed as the one who paid kurachi to attack ayanokoji  investigates his attacker without his permission   a  defence plan  of her own","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4_5-p182-1\"><h3><span class=\"ttl\">Nanase and Ryūen interrogate Kurachi (the cliff attacker)<\/span><span class=\"meta\">Y2V4.5 · p.182–191<\/span><\/h3><p class=\"setup\">Ryūen (investigating who pushed Komiya) stops Nanase during the treasure hunt; she agrees to help question Kurachi Naohiro, the first-year who attacked Ayanokōji on day seven.<\/p><p class=\"with\">with <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;Nanase Tsubasa, right?&quot;<span class=\"pg\">p.183<\/span><\/li><li class=\"q spoken\">&quot;Tell me why you were targeting Ayanokōji-senpai during the uninhabited island exam.&quot;<span class=\"pg\">p.188<\/span><\/li><li class=\"q spoken\">&quot;is urgently trying to find the culprit who almost attacked Ayanokōji-senpai.&quot;<span class=\"pg\">p.188<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I was told I&#x27;d be given money if I attacked Ayanokōji-senpai…&quot;<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Give me time. Of course, I don&#x27;t mean for free.&quot;<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Deftly interrogates Kurachi using the threat of Hōsen&#x27;s fists (plus Ryūen behind her), learns Utomiya Riku paid him (anonymously, before the exam) to &quot;pretend&quot; to attack Ayanokōji; brokers a deal with Ryūen — she&#x27;ll reveal a witness in Komiya&#x27;s case if he doesn&#x27;t contact Utomiya yet.<span class=\"pg\">p.182–191<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Works with him (reluctantly) to find the attacker; he wants to confront Utomiya, she negotiates delay.<span class=\"pg\">p.182–191<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> Revealed as the one who paid Kurachi to attack Ayanokōji.<span class=\"pg\">p.189–190<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Investigates his attacker without his permission — a &quot;defence plan&quot; of her own.<span class=\"pg\">p.188<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4_5-p283-1\">→ After: Short story: &quot;A Double-sided Favour Repayment&quot; — tailing Kurachi<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4_5-p283-1","v":"y2v4.5","y":2,"o":20,"k":"narration","w":"ayanokouji-kiyotaka kurachi nanase-tsubasa","q":"nanase tsubasa short story   a double sided favour repayment    tailing kurachi from her own pov  tails first year kurachi through the store  buying a sandwich and milk to blend in   he appeared on her gps search for ayanokoji s attacker   because if i could leave behind at least something for ayanokouji senpai  it would have been worth it   yes  this is my own decision   nanase   phease huht waid a bid   sorry  that s something i ve already taken care of so can i ask you to forget about it   i m sorry  ayanokouji senpai  i already knew i should have just told you all this upfront  devoted and secretive   she s investigating the attack on her own  keeping it from ayanokoji  to leave behind  some accomplishments  refuses the easy path of letting him  pamper  her  and hides the tailing from him even when he calls her out   apologizing internally  resolved to  work hard  for him  the  double sided favour  of the title reflects her divided loyalty  she hides her investigation from him  then regrets it   he s too kind and would have stopped her  the first year she tails   suspect in the attack on ayanokoji","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4_5-p283-1\"><h3><span class=\"ttl\">Short story: &quot;A Double-sided Favour Repayment&quot; — tailing Kurachi<\/span><span class=\"meta\">Y2V4.5 · p.283–286<\/span><\/h3><p class=\"setup\">From her own POV, tails first-year Kurachi through the store, buying a sandwich and milk to blend in — he appeared on her GPS search for Ayanokōji&#x27;s attacker.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"index.html#kurachi\">Kurachi<\/a><\/p><ul class=\"lines\"><li class=\"q narration\">&quot;Because if I could leave behind at least something for Ayanokouji-senpai, it would have been worth it.&quot;<span class=\"pg\">p.283<\/span><\/li><li class=\"q narration\">&quot;Yes, this is my own decision.&quot;<span class=\"pg\">p.283<\/span><\/li><li class=\"q narration\">&quot;Nanase.&quot;<span class=\"pg\">p.284<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;Phease huht waid a bid.&quot;<span class=\"pg\">p.284<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;Sorry, That&#x27;s something I&#x27;ve already taken care of so can I ask you to forget about it?&quot;<span class=\"pg\">p.285<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;I&#x27;m sorry, Ayanokouji-senpai… I already knew I should have just told you all this upfront.&quot;<span class=\"pg\">p.286<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Devoted and secretive — she&#x27;s investigating the attack on her own (keeping it from Ayanokōji) to leave behind &quot;some accomplishments,&quot; refuses the easy path of letting him &quot;pamper&quot; her, and hides the tailing from him even when he calls her out — apologizing internally, resolved to &quot;work hard&quot; for him; the &quot;double-sided favour&quot; of the title reflects her divided loyalty.<span class=\"pg\">p.283–286<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She hides her investigation from him, then regrets it — he&#x27;s too kind and would have stopped her.<span class=\"pg\">p.284–286<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kurachi<\/b> The first-year she tails — suspect in the attack on Ayanokōji.<span class=\"pg\">p.283–285<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4_5-p182-1\">← Before: Nanase and Ryūen interrogate Kurachi (the cliff attacker)<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v6-p11-1","v":"y2v6","y":2,"o":22,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa nanase tsubasa mentioned in passing named in this volume  passing mentions on pages  p 274  p 276  p 279 284  passing mention only","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v6-p11-1\"><h3><span class=\"ttl\">nanase-tsubasa mentioned in passing<\/span><span class=\"meta\">Y2V6 · p.11-346<\/span><\/h3><p class=\"setup\">Named in this volume.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mentions on pages: p.274, p.276, p.279-284.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.11<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-nanase-tsubasa-y2v7-p7-1","v":"y2v7","y":2,"o":23,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa nanase tsubasa mentioned in passing named in this volume  passing mentions on pages  p 108  passing mention only","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v7-p7-1\"><h3><span class=\"ttl\">nanase-tsubasa mentioned in passing<\/span><span class=\"meta\">Y2V7 · p.7-207<\/span><\/h3><p class=\"setup\">Named in this volume.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mentions on pages: p.108.<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.7<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-nanase-tsubasa-y2v8-p28-1","v":"y2v8","y":2,"o":24,"k":"spoken","w":"ayanokouji-kiyotaka yagami-takuya amasawa-ichika nanase-tsubasa","q":"nanase tsubasa nanase  yagami s fear  warnings about the trip  i think he was scared  yagami was afraid of fighting ayanokoji senpai   i want ayanokoji senpai to remain at this school and graduate   the outside world is full of danger  reports a first year s approach to him  reveals yagami was  scared  of fighting ayanokoji  why he lashed out  and warns about dangers on the school trip   the outside world  possible white room involvement  family registers  now openly wants him to stay and graduate  and chides him for being too calm about the danger  she worried about him on the trip    i can t believe i m the one worried about ayanokoji senpai  he was  afraid of fighting  ayanokoji   explains his rampage  he brings up amasawa  she has no new information about her plans for the trip","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v8-p28-1\"><h3><span class=\"ttl\">Nanase: Yagami&#x27;s fear; warnings about the trip<\/span><span class=\"meta\">Y2V8 · p.28–38<\/span><\/h3><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"yagami-takuya.html\">Yagami Takuya<\/a> · <a href=\"amasawa-ichika.html\">Amasawa Ichika<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;I think he was scared. Yagami was afraid of fighting Ayanokōji-senpai.&quot;<span class=\"pg\">p.32<\/span><\/li><li class=\"q spoken\">&quot;I want Ayanokōji-senpai to remain at this school and graduate.&quot;<span class=\"pg\">p.33<\/span><\/li><li class=\"q spoken\">&quot;the outside world is full of danger.&quot;<span class=\"pg\">p.35<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Reports a first-year&#x27;s approach to him, reveals Yagami was &quot;scared&quot; of fighting Ayanokōji (why he lashed out), and warns about dangers on the school trip — the outside world, possible White Room involvement (family registers); now openly wants him to stay and graduate, and chides him for being too calm about the danger.<span class=\"pg\">p.28–38<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She worried about him on the trip — &quot;I can&#x27;t believe I&#x27;m the one worried about Ayanokōji-senpai.&quot;<span class=\"pg\">p.32–38<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yagami Takuya<\/b> He was &quot;afraid of fighting&quot; Ayanokōji — explains his rampage.<span class=\"pg\">p.32<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> He brings up Amasawa; she has no new information about her plans for the trip.<span class=\"pg\">p.34–37<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-nanase-tsubasa-y2v9-p67-1","v":"y2v9","y":2,"o":25,"k":"spoken","w":"horikita-suzune kushida-kikyou nanase-tsubasa","q":"nanase tsubasa nanase  accepted onto the student council horikita invites her to join the student council  she happily agrees  exchanges contact details  and says she is glad to gain more contacts   umm  what should i do from tomorrow onwards   i m glad to have more contacts as well   yes  i m looking forward to hearing from you  she arrives at the council room  greets horikita politely and chats easily with kushida  nagumo formally approves her as a new member from class 1 d   good evening  horikita senpai  cheerful  socially eager and polite   delighted at the chance to join and quick to bond with her fellow new member  recruited by her  calls her senpai  hits it off with her immediately in the council room","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v9-p67-1\"><h3><span class=\"ttl\">Nanase: accepted onto the student council<\/span><span class=\"meta\">Y2V9 · p.67–73<\/span><\/h3><p class=\"setup\">Horikita invites her to join the student council; she happily agrees, exchanges contact details, and says she is glad to gain more contacts. She arrives at the council room, greets Horikita politely and chats easily with Kushida; Nagumo formally approves her as a new member from Class 1-D.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Umm, what should I do from tomorrow onwards?&quot;<span class=\"pg\">p.67<\/span><\/li><li class=\"q spoken\">&quot;I&#x27;m glad to have more contacts as well!&quot;<span class=\"pg\">p.67<\/span><\/li><li class=\"q spoken\">&quot;Yes, I&#x27;m looking forward to hearing from you!&quot;<span class=\"pg\">p.67<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Good evening, Horikita-senpai.&quot;<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Cheerful, socially eager and polite — delighted at the chance to join and quick to bond with her fellow new member.<span class=\"pg\">p.67–73<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Recruited by her; calls her senpai.<span class=\"pg\">p.67–73<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Hits it off with her immediately in the council room.<span class=\"pg\">p.73<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-nanase-tsubasa-y2v9_5-p63-1","v":"y2v9.5","y":2,"o":26,"k":"spoken","w":"ichinose-honami housen-kazuomi nanase-tsubasa","q":"nanase tsubasa ch 3  christmas photo with ichinose and hosen finds ichinose and ayanokoji mid photo session  joins  together they pose  she bumps into hosen and drags him over  pushes hosen into the photo  later whispers to ayanokoji that hosen came because he likes ichinose  used her to get close   sorry  can you wait a moment  photo partner  ferry service between hosen and the mall  she walks ahead of him  relays his intent to ayanokoji in confidence","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v9_5-p63-1\"><h3><span class=\"ttl\">Ch.3: Christmas photo with Ichinose and Hōsen<\/span><span class=\"meta\">Y2V9.5 · p.63–65<\/span><\/h3><p class=\"setup\">Finds Ichinose and Ayanokōji mid-photo-session; joins; together they pose; she bumps into Hōsen and drags him over. Pushes Hōsen into the photo; later whispers to Ayanokōji that Hōsen came because he likes Ichinose; used her to get close.<\/p><p class=\"with\">with <a href=\"ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Sorry, can you wait a moment?&quot;<span class=\"pg\">p.63<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Photo partner; ferry service between Hōsen and the mall.<span class=\"pg\">p.63–65<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> She walks ahead of him; relays his intent to Ayanokōji in confidence.<span class=\"pg\">p.64–65<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-nanase-tsubasa-y2v11-p70-1","v":"y2v11","y":2,"o":30,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa ch 2  the oshibana match group 9   horikita s class   lines up against group 20 for the day 1 oshibana match  nanase asks kiyotaka about oshibana   do you also make oshibana  ayanokoji senpai   i see  i thought you were good at it because you were the only boy participating   please go easy on me  nine out of ten participants are girls  kiyotaka wins his head to head with her  the group takes 3 2  she meets him as an opponent and loses  he compliments the field","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v11-p70-1\"><h3><span class=\"ttl\">Ch.2: The oshibana match<\/span><span class=\"meta\">Y2V11 · p.70–71<\/span><\/h3><p class=\"setup\">Group 9 — Horikita&#x27;s class — lines up against Group 20 for the Day 1 oshibana match; Nanase asks Kiyotaka about oshibana.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Do you also make oshibana, Ayanokōji-senpai?”<span class=\"pg\">p.70<\/span><\/li><li class=\"q spoken\">“I see. I thought you were good at it because you were the only boy participating.”<span class=\"pg\">p.71<\/span><\/li><li class=\"q spoken\">“Please go easy on me.”<span class=\"pg\">p.71<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Nine out of ten participants are girls; Kiyotaka wins his head-to-head with her; the group takes 3–2.<span class=\"pg\">p.71<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She meets him as an opponent and loses; he compliments the field.<span class=\"pg\">p.70–71<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-nanase-tsubasa-y2v12-p12-1","v":"y2v12","y":2,"o":31,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa nanase tsubasa mentioned in passing named in this volume  passing mention  locator pages  p 40  not line by line verified  substring false positives possible  not a scene presence  passing mention only","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v12-p12-1\"><h3><span class=\"ttl\">nanase-tsubasa mentioned in passing<\/span><span class=\"meta\">Y2V12 · p.12-228<\/span><\/h3><p class=\"setup\">Named in this volume.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention (locator pages: p.40; not line-by-line verified; substring false positives possible). Not a scene presence.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.12<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-nanase-tsubasa-y2v12_5-p148-1","v":"y2v12.5","y":2,"o":32,"k":"","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa ch 9 mentioned appears in ch 9  appears in this volume","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v12_5-p148-1\"><h3><span class=\"ttl\">Ch.9<\/span><span class=\"meta\">Y2V12.5 · p.148-176<\/span><\/h3><p class=\"setup\">Mentioned/appears in Ch.9.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Appears in this volume.<span class=\"pg\">p.148-176<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p10-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"tsukishiro ayanokouji-kiyotaka ayanokouji-atsuomi nanase-tsubasa","q":"nanase tsubasa prologue   depth read  tsukishiro s offer sits beside the unconscious matsuo eiichirou in his hospital room  overwhelmed with regret   how did it come to this   if i d noticed something was wrong with eiichirou kun  this wouldn t have happened   i have brought you an opportunity to exact your revenge   attending anhs is the only way to get close to your target   my apologies  my name is tsukishiro  i ve been well acquainted with you and matsuo kun sleeping here  since you were children   you must mix lies with the truth  her goal has shifted from revenge   to help ayanokoji so he won t become a  pure evil  who creates more victims like eiichirou  is recruited by him to get close to ayanokoji in exchange for revenge  is tasked with approaching him as an insignificant being  now wants to save him  holds him responsible for cornering eiichirou   the true target of her revenge  tsukishiro s mention of  shirogane san  proves he knew nanase since childhood  eiichirou is in a vegetative state   a  prolonged disturbance of consciousness","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p10-1\"><h3><span class=\"ttl\">Prologue — depth read: Tsukishiro&#x27;s offer<\/span><span class=\"meta\">Y3V2 · p.10–12<\/span><\/h3><p class=\"setup\">Sits beside the unconscious Matsuo Eiichirou in his hospital room, overwhelmed with regret.<\/p><p class=\"with\">with <a href=\"tsukishiro.html\">Tsukishiro<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;How did it come to this—&quot;<span class=\"pg\">p.10<\/span><\/li><li class=\"q spoken\">&quot;If I&#x27;d noticed something was wrong with Eiichirou-kun, this wouldn&#x27;t have happened.&quot;<span class=\"pg\">p.10<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> &quot;I have brought you an opportunity to exact your revenge.&quot;<span class=\"pg\">p.10<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Attending ANHS is the only way to get close to your target—&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;My apologies. My name is Tsukishiro. I&#x27;ve been well acquainted with you and Matsuo-kun sleeping here, since you were children.&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You must mix lies with the truth.&quot;<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Her goal has shifted from revenge — to help Ayanokōji so he won&#x27;t become a &quot;pure evil&quot; who creates more victims like Eiichirou.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Is recruited by him to get close to Ayanokōji in exchange for revenge.<span class=\"pg\">p.10–12<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is tasked with approaching him as an insignificant being; now wants to save him.<span class=\"pg\">p.11–12<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Atsuomi<\/b> Holds him responsible for cornering Eiichirou — the true target of her revenge.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tsukishiro&#x27;s mention of &quot;Shirogane-san&quot; proves he knew Nanase since childhood.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Eiichirou is in a vegetative state — a &quot;prolonged disturbance of consciousness.&quot;<span class=\"pg\">p.10<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p10-2\">→ After: Nanase at Eiichirou&#x27;s bedside; Tsukishiro&#x27;s offer<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p10-2","v":"y3v2","y":3,"o":34,"k":"narration spoken","w":"tsukishiro nanase-tsubasa","q":"nanase tsubasa nanase at eiichirou s bedside  tsukishiro s offer sits beside matsuo eiichirou in his hospital room  murmuring  how did it come to this  as he lies in a vegetative state   how did it come to this   yes  if i  if i d noticed something was wrong with eiichirou kun  this wouldn t have happened  no  i never would have let something like this happen  eiichirou suffers from a  prolonged disturbance of consciousness    a vegetative state  he can open his eyes and breathe but isn t conscious or responsive  doctors gave a slim chance of recovery within weeks or months   you cannot survive in this world on kindness alone  no  in fact  you ll be preyed upon by fiends so wicked they are beyond salvation   the world works on give and take  you understand that  yes   yes  i am grateful for your considerable support  after visiting hospital after hospital  tsukishiro was the one who found a place that would accept eiichirou  thirty minutes later and he might not have survived   what is it you want me to do   i have brought you an opportunity to exact your revenge   i will teach you how to get close to the person you should take revenge on  he offers her revenge in exchange for getting close to a target","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p10-2\"><h3><span class=\"ttl\">Nanase at Eiichirou&#x27;s bedside; Tsukishiro&#x27;s offer<\/span><span class=\"meta\">Y3V2 · p.10–11<\/span><\/h3><p class=\"setup\">Sits beside Matsuo Eiichirou in his hospital room, murmuring &quot;How did it come to this—&quot; as he lies in a vegetative state.<\/p><p class=\"with\">with <a href=\"tsukishiro.html\">Tsukishiro<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;HOW DID IT come to this—&quot;<span class=\"pg\">p.10<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> &quot;You cannot survive in this world on kindness alone. No, in fact, you&#x27;ll be preyed upon by fiends so wicked they are beyond salvation—&quot;<span class=\"pg\">p.10<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> &quot;The world works on give-and-take. You understand that, yes?&quot;<span class=\"pg\">p.10<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;...Yes... If I... If I&#x27;d noticed something was wrong with Eiichirou-kun, this wouldn&#x27;t have happened, no... I never would have let something like this happen...&quot;<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Eiichirou suffers from a &quot;prolonged disturbance of consciousness&quot; — a vegetative state: he can open his eyes and breathe but isn&#x27;t conscious or responsive; doctors gave a slim chance of recovery within weeks or months.<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Yes. I am grateful for your considerable support.&quot;<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> After visiting hospital after hospital, Tsukishiro was the one who found a place that would accept Eiichirou; thirty minutes later and he might not have survived.<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;What is it you want me to do?&quot;<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I have brought you an opportunity to exact your revenge.&quot;<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I will teach you how to get close to the person you should take revenge on.&quot;<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> He offers her revenge in exchange for getting close to a target.<span class=\"pg\">p.10–11<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p10-1\">← Before: Prologue — depth read: Tsukishiro&#x27;s offer<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p11-1\">→ After: Learning the target; Tsukishiro&#x27;s true nature<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p11-1","v":"y3v2","y":3,"o":34,"k":"narration spoken","w":"tsukishiro ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa learning the target  tsukishiro s true nature tsukishiro places an application form and photograph on the portable table   what is this   attending anhs is the only way to get close to your target   i realize i haven t asked your name  who are you   my apologies  my name is tsukishiro  i ve been well acquainted with you and matsuo kun sleeping here  since you were children   i ve seen plenty of adults approach me  pretending to know things when they really know nothing   is shirogane san doing well  the name shirogane makes her body react unconsciously  betraying her feigned composure   he knew them since childhood  and she instantly understands he is telling the truth   you re not evil  but the inhabitants of the world i live in are nothing but evil   you re ordinary  yet excellent  ordinary  yet immature  ordinary  yet talented   you re tsukishiro san  you said  is this boy connected to that evil   he is ayanokouji kiyotaka  a key figure who will lead you to the target of your revenge  tsukishiro s mention of shirogane    she took good care of me when i was young    reveals he knew nanase and eiichirou since childhood  shirogane is not on the roster  identified in the photograph as the key figure leading to her revenge target","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p11-1\"><h3><span class=\"ttl\">Learning the target; Tsukishiro&#x27;s true nature<\/span><span class=\"meta\">Y3V2 · p.11–12<\/span><\/h3><p class=\"setup\">Tsukishiro places an application form and photograph on the portable table.<\/p><p class=\"with\">with <a href=\"tsukishiro.html\">Tsukishiro<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> &quot;Attending ANHS is the only way to get close to your target—&quot;<span class=\"pg\">p.11<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> &quot;My apologies. My name is Tsukishiro. I&#x27;ve been well acquainted with you and Matsuo-kun sleeping here, since you were children.&quot;<span class=\"pg\">p.11<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> &quot;Is Shirogane-san doing well?&quot;<span class=\"pg\">p.11<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;What is this...?&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;...I realize I haven&#x27;t asked your name... Who are you?&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;I&#x27;ve seen plenty of adults approach me, pretending to know things when they really know nothing.&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> The name Shirogane makes her body react unconsciously, betraying her feigned composure — he knew them since childhood, and she instantly understands he is telling the truth.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You&#x27;re not evil. But the inhabitants of the world I live in are nothing but evil.&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You&#x27;re ordinary, yet excellent. Ordinary, yet immature. Ordinary, yet talented.&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;You&#x27;re Tsukishiro-san, you said. Is this boy connected to that evil?&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;He is Ayanokouji Kiyotaka, a key figure who will lead you to the target of your revenge.&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tsukishiro&#x27;s mention of Shirogane — &quot;she took good care of me when I was young&quot; — reveals he knew Nanase and Eiichirou since childhood (Shirogane is not on the roster).<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Identified in the photograph as the key figure leading to her revenge target.<span class=\"pg\">p.11<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p10-2\">← Before: Nanase at Eiichirou&#x27;s bedside; Tsukishiro&#x27;s offer<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p12-1\">→ After: Accepting the mission; the motive shifts<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p12-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"tsukishiro nanase-tsubasa","q":"nanase tsubasa accepting the mission  the motive shifts  that boy  though inorganic  has outstanding  refined instincts  if you approach him carelessly  he will easily see through you   then  what should i do   you must mix lies with the truth   he will naturally be suspicious of you  but he won t delve too deeply  that is because he will recognize you as an insignificant being   let me ask one last thing  why me   it is because you are in a perfect position  neither clearly on one side  nor the other  she nods without a pause   at that time her heart was set on revenge against ayanokouji atsuomi  the one who cornered eiichirou  her motive has since shifted  she now wants to help ayanokouji senpai  believing that if he graduates as he is  he will walk a path of  pure evil  and create more victims like eiichirou   so  knowing that predicament firsthand  she must stop it  shirogane is not on the roster   tsukishiro s remark is recorded here  not as a  rel  to a non existent id","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p12-1\"><h3><span class=\"ttl\">Accepting the mission; the motive shifts<\/span><span class=\"meta\">Y3V2 · p.12<\/span><\/h3><p class=\"with\">with <a href=\"tsukishiro.html\">Tsukishiro<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> &quot;That boy, though inorganic, has outstanding, refined instincts. If you approach him carelessly, he will easily see through you.&quot;<span class=\"pg\">p.12<\/span><\/li><li class=\"q spoken\">&quot;Then, what should I do?&quot;<span class=\"pg\">p.12<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> &quot;You must mix lies with the truth.&quot;<span class=\"pg\">p.12<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;He will naturally be suspicious of you, but he won&#x27;t delve too deeply. That is because he will recognize you as an insignificant being.&quot;<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Let me ask one last thing. Why me?&quot;<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It is because you are in a perfect position. Neither clearly on one side, nor the other.&quot;<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> She nods without a pause — at that time her heart was set on revenge against Ayanokouji Atsuomi, the one who cornered Eiichirou.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Her motive has since shifted: she now wants to help Ayanokouji-senpai, believing that if he graduates as he is, he will walk a path of &quot;pure evil&quot; and create more victims like Eiichirou — so, knowing that predicament firsthand, she must stop it.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Shirogane is not on the roster — Tsukishiro&#x27;s remark is recorded here, not as a `[rel:]` to a non-existent id.<span class=\"pg\">p.12<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p11-1\">← Before: Learning the target; Tsukishiro&#x27;s true nature<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p66-1\">→ After: Ch.3 — depth read: Nanase and the first-year fight<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p66-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"horikita-suzune nanase-tsubasa","q":"nanase tsubasa ch 3   depth read  nanase and the first year fight works with horikita in the student council room on the case of first years kusanagi and maki   you mean their pride was wounded because they lost a two on one fight  it s not out of the question  but would they really be that tight lipped about it   of course  student council president  but being the president is a lot of work  isn t it  you re amazing  horikita senpai   no mediocre  even so  i think that s fine  a mediocre horikita senpai isn t bad at all   w wha  i i m so sorry  i think student council president horikita is very admirable  helpful but awkward   blurted out the honest view that being mediocre is fine and panicked  trying to smooth it over  assists her in the investigation and is asked to help uncover the truth  the two first years kusanagi minato and maki yuuma got into a fight  neither would report it  hinting a third party  possibly a girl  was involved","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p66-1\"><h3><span class=\"ttl\">Ch.3 — depth read: Nanase and the first-year fight<\/span><span class=\"meta\">Y3V2 · p.66–125<\/span><\/h3><p class=\"setup\">Works with Horikita in the student council room on the case of first-years Kusanagi and Maki.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;You mean their pride was wounded because they lost a two-on-one fight? It&#x27;s not out of the question, but would they really be that tight-lipped about it?&quot;<span class=\"pg\">p.87<\/span><\/li><li class=\"q spoken\">&quot;Of course, Student Council President. But being the president is a lot of work, isn&#x27;t it? You&#x27;re amazing, Horikita-senpai.&quot;<span class=\"pg\">p.87<\/span><\/li><li class=\"q spoken\">&quot;No—mediocre. Even so, I think that&#x27;s fine. A mediocre Horikita-senpai isn&#x27;t bad at all.&quot;<span class=\"pg\">p.88<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;W-Wha—!? I-I&#x27;m so sorry! I think Student Council President Horikita is very admirable!&quot;<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Helpful but awkward — blurted out the honest view that being mediocre is fine and panicked, trying to smooth it over.<span class=\"pg\">p.87–88<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Assists her in the investigation and is asked to help uncover the truth.<span class=\"pg\">p.85–88<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The two first-years Kusanagi Minato and Maki Yuuma got into a fight; neither would report it, hinting a third party (possibly a girl) was involved.<span class=\"pg\">p.86<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p12-1\">← Before: Accepting the mission; the motive shifts<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p211-1\">→ After: Ch.7 — depth read: Nanase works the White Room angle<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p211-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"shiraishi-asuka tsukishiro ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa ch 7   depth read  nanase works the white room angle meets shiraishi back to back in a quiet restaurant  having called her out   have i kept you waiting   why is that   then why have you started to close the distance now   i am from that side   at least give me some information  please  just disclose the names of your associates   that if i am expelled before ayanokouji senpai s fate is decided  things may very well head in a direction that shirogane sensei would not desire  cautious and probing   arranged a covert meeting  tries to read shiraishi through emphases and emphasized names  and aligns herself with tsukishiro s anti ayanokoji faction  demands her cooperation intelligence  is refused  and warns her of consequences if expelled  reveals she is aligned with his faction  that side superiors  is working against him  refers to him as  ayanokouji senpai  cites  shirogane sensei  in her warning   a name tied to her past  not on the roster","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p211-1\"><h3><span class=\"ttl\">Ch.7 — depth read: Nanase works the White Room angle<\/span><span class=\"meta\">Y3V2 · p.211–230<\/span><\/h3><p class=\"setup\">Meets Shiraishi back-to-back in a quiet restaurant, having called her out.<\/p><p class=\"with\">with <a href=\"shiraishi-asuka.html\">Shiraishi Asuka<\/a> · <a href=\"tsukishiro.html\">Tsukishiro<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Have I kept you waiting?&quot;<span class=\"pg\">p.226<\/span><\/li><li class=\"q spoken\">&quot;Why...is that?&quot;<span class=\"pg\">p.228<\/span><\/li><li class=\"q spoken\">&quot;Then why have you started to close the distance now?&quot;<span class=\"pg\">p.229<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I am from that side.&quot;<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;At least give me some information... Please, just disclose the names of your associates.&quot;<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;That if I am expelled before Ayanokouji-senpai&#x27;s fate is decided... things may very well head in a direction that Shirogane-sensei would not desire.&quot;<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Cautious and probing — arranged a covert meeting, tries to read Shiraishi through emphases and emphasized names, and aligns herself with Tsukishiro&#x27;s anti-Ayanokōji faction.<span class=\"pg\">p.226–230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiraishi Asuka<\/b> Demands her cooperation/intelligence; is refused, and warns her of consequences if expelled.<span class=\"pg\">p.226–230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Reveals she is aligned with his faction (&quot;that side&quot;/&quot;superiors&quot;).<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is working against him; refers to him as &quot;Ayanokouji-senpai.&quot;<span class=\"pg\">p.226–230<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Cites &quot;Shirogane-sensei&quot; in her warning — a name tied to her past (not on the roster).<span class=\"pg\">p.230<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p66-1\">← Before: Ch.3 — depth read: Nanase and the first-year fight<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p226-1\">→ After: Nanase&#x27;s secret meeting: asking Shiraishi to expel Ayanokōji<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p226-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"shiraishi-asuka ayanokouji-kiyotaka tsukishiro hashimoto-masayoshi morishita-ai nanase-tsubasa","q":"nanase tsubasa nanase s secret meeting  asking shiraishi to expel ayanokoji sits back to back with shiraishi in a quiet restaurant  having contacted her in violation of the rules   are you really sure this was the right place to meet   it s true that it s easier to talk since there are few customers  but on the flip side  that means we inevitably stand out   i want to get ayanokouji senpai expelled  as soon as possible  and at a time he can t predict   then why have you started to close the distance now   i will take action while ayanokouji senpai is still within reach   at least give me some information  please  just disclose the names of your associates  cautious and probing   uses a back to back meeting  deliberately emphasizes  nishikawa  to read shiraishi s reaction  admits carelessness with the second phone  and grows impatient in her goal to expel ayanokoji  aligns herself with tsukishiro s anti ayanokoji faction  tries to recruit her  refused  but leaves with a warning about shirogane  wants him expelled as soon as possible  her  superior  in the anti ayanokoji faction  recorded via shiraishi s line  shiraishi silenced him after he witnessed nanase s second phone  likewise silenced","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p226-1\"><h3><span class=\"ttl\">Nanase&#x27;s secret meeting: asking Shiraishi to expel Ayanokōji<\/span><span class=\"meta\">Y3V2 · p.226–230<\/span><\/h3><p class=\"setup\">Sits back-to-back with Shiraishi in a quiet restaurant, having contacted her in violation of the rules.<\/p><p class=\"with\">with <a href=\"shiraishi-asuka.html\">Shiraishi Asuka<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"tsukishiro.html\">Tsukishiro<\/a> · <a href=\"hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a> · <a href=\"morishita-ai.html\">Morishita Ai<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Are you really sure this was the right place to meet?&quot;<span class=\"pg\">p.226<\/span><\/li><li class=\"q spoken\">&quot;It&#x27;s true that it&#x27;s easier to talk since there are few customers, but on the flip side, that means we inevitably stand out.&quot;<span class=\"pg\">p.227<\/span><\/li><li class=\"q spoken\">&quot;I want to get Ayanokouji-senpai expelled. As soon as possible, and at a time he can&#x27;t predict.&quot;<span class=\"pg\">p.228<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Then why have you started to close the distance now?&quot;<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I will take action while Ayanokouji-senpai is still within reach.&quot;<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;At least give me some information... Please, just disclose the names of your associates.&quot;<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Cautious and probing — uses a back-to-back meeting, deliberately emphasizes &quot;Nishikawa&quot; to read Shiraishi&#x27;s reaction, admits carelessness with the second phone, and grows impatient in her goal to expel Ayanokōji; aligns herself with Tsukishiro&#x27;s anti-Ayanokōji faction.<span class=\"pg\">p.226–230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiraishi Asuka<\/b> Tries to recruit her; refused, but leaves with a warning about Shirogane.<span class=\"pg\">p.226–230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Wants him expelled as soon as possible.<span class=\"pg\">p.228–229<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Her &quot;superior&quot; in the anti-Ayanokōji faction (recorded via Shiraishi&#x27;s line).<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Shiraishi silenced him after he witnessed Nanase&#x27;s second phone.<span class=\"pg\">p.228<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Morishita Ai<\/b> Likewise silenced.<span class=\"pg\">p.228<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p211-1\">← Before: Ch.7 — depth read: Nanase works the White Room angle<\/button><\/div><\/article>"}];
